package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** Approved three-column composition, using only server-supported appearance/role choices. */
final class SurvivorCreationView extends View {
 interface Host{void create(String appearance,String faction,String profession);String status();String legacyProfession();void back();}
 private final Host host;private final MenuFrame f=new MenuFrame();private final MenuArt art;private final ScenePainter survivor=new ScenePainter();private int sex,body,role,faction;private float downX,downY;
 SurvivorCreationView(Context c,Host h){super(c);host=h;art=MenuArt.get(c);setContentDescription("Create survivor: male or female, lean or sturdy, Farmer or Hunter, Survivor or Bandit allegiance.");}
 private String appearance(){return(sex==1?"female-":"male-")+(body==1?"2":"1");}
 private String profession(){return host.legacyProfession().isEmpty()?(role==0?"farmer":"hunter"):host.legacyProfession();}
 protected void onDraw(Canvas c){f.begin(c,this);f.text(c,"FORSAKEN REALM / CREATE YOUR SURVIVOR",24,40,25,910);f.panel(c,24,77,218,366,false);f.text(c,"APPEARANCE",39,106,19,188);String[][] labels={{"MALE","FEMALE"},{"LEAN","STURDY"},{"SURVIVOR","BANDIT"}};String[] headings={"GENDER","BODY STYLE","ALLEGIANCE"};for(int row=0;row<3;row++){float y=142+row*100;f.text(c,headings[row],40,y-12,13,186);int chosen=row==0?sex:row==1?body:faction;for(int i=0;i<2;i++){float x=38+i*97;f.panel(c,x,y,91,56,i==chosen);f.text(c,labels[row][i],x+8,y+33,15,75);}}
 f.panel(c,259,77,340,366,false);f.text(c,"YOUR SURVIVOR",282,108,19,292);JSONObject gear=new JSONObject();try{gear.put("appearance",appearance()).put("inventory",new JSONObject()).put("armorSlots",new JSONObject());}catch(JSONException ignored){}c.save();c.clipRect(270,122,588,412);c.translate(427,402);c.scale(3.5f,3.5f);survivor.actor(c,"you:unarmed",0,0,0xff66776a,0,false,-1,false,0,gear);c.restore();f.text(c,appearance().startsWith("female")?"FEMALE":"MALE",374,429,14,170);
 f.panel(c,616,77,320,366,false);f.text(c,"CHOOSE YOUR ROLE",634,108,19,282);boolean legacy=!host.legacyProfession().isEmpty();int count=legacy?1:2;for(int i=0;i<count;i++){float y=127+i*100;f.panel(c,632,y,288,89,legacy||role==i);String name=legacy?profession().toUpperCase():i==0?"FARMER":"HUNTER";if(!legacy)art.role(c,i,new RectF(638,y+6,706,y+82));f.text(c,name,715,y+29,19,194);f.wrap(c,legacy?"Your existing role and equipment are retained.":i==0?"Food and settlement. Axe, sickle and seeds. Companion: Horse.":"Hunting and ranged combat. Bow and arrows. Companion: Wolf.",715,y+50,193,2);}f.text(c,"ROLE & PROGRESS ARE SAVED",635,369,13,280);f.wrap(c,"Appearance changes do not grant extra stats.",635,394,276,2);
 f.panel(c,24,466,187,48,false);f.text(c,"< BACK",49,498,18,143);f.panel(c,616,466,320,48,true);f.text(c,"CONFIRM CHARACTER",645,498,21,265);f.text(c,host.status(),227,496,12,370);c.restore();}
 public boolean performClick(){super.performClick();return true;}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=x;downY=y;return true;}if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;if(Math.hypot(x-downX,y-downY)>14)return true;performClick();if(x>=38&&x<=226){for(int row=0;row<3;row++){float top=142+row*100;if(y>=top&&y<=top+56){int choice=x>=135?1:0;if(row==0)sex=choice;else if(row==1)body=choice;else faction=choice;}}}if(host.legacyProfession().isEmpty()&&x>=632&&x<=920&&y>=127&&y<=316&&(y-127)%100<=89)role=(int)((y-127)/100);if(y>=466&&y<=514){if(x>=24&&x<=211)host.back();else if(x>=616&&x<=936)host.create(appearance(),faction==0?"survivor":"bandit",profession());}invalidate();return true;}
}
